def transform(grid):
    h, w = len(grid), len(grid[0])

    # The full-width and full-height lines are the panel separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    sep_color = grid[sep_rows[0]][0]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    panels = [
        (row_bounds[i] + 1, row_bounds[i + 1],
         col_bounds[j] + 1, col_bounds[j + 1])
        for i in range(len(row_bounds) - 1)
        for j in range(len(col_bounds) - 1)
    ]

    nr, nc = len(row_bounds) - 1, len(col_bounds) - 1

    # Find the motif in a panel beyond the first column.
    motif = set()
    for i in range(nr):
        for j in range(1, nc):
            r0, r1, c0, c1 = panels[i * nc + j]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] != 0 and grid[r][c] != sep_color:
                        motif.add((r - r0, c - c0))
    if not motif:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for i in range(nr):
        r0, r1, c0, c1 = panels[i * nc]
        colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                  if grid[r][c] != 0 and grid[r][c] != sep_color]
        if not colors:
            continue
        color = colors[0]

        for j in range(nc):
            a, b, x, y = panels[i * nc + j]
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = 0
            for dr, dc in motif:
                if a + dr < b and x + dc < y:
                    out[a + dr][x + dc] = color

    return out
